#define PI 3.14159265358979
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))// 

void mainImage(out vec4 O, vec2 U){
        O = vec4(0);
        vec2 R = iResolution.xy,
             p = (U+U - R)/R.y;
             p.y +=1.;

             p = .1*p;

        vec2 a,b,c,d,e,f,g,h,  u,v, w, uv, vw;

        float s=1., k = 1./(1.+sqrt(2.)), type ;

        // trangle (a,b,c) and trangle (u,v,w)
        b.x = 1.;
        a = -b;
        c = b.yx;
        f.x = k;
        e = f.yx;
        d = -f;
        g = vec2(0, 1)-k;
        h = vec2(1.-k, k);

        u.y = sqrt(2.)*sin(PI/8.);
        v.x = sqrt(2.)*cos(PI/8.);


        uv = u +(v-u)*(1.-k);
        vw = -v+(v+v)*(1.-k);

        //vec2 ag5=(a+g)*.5,  hc5 eg5 eb5 vw5 uuv5
        type=0.;

        for(int i =0; i<5; i++)
        {
                if(type<.5)
                {
                        if(p.x<0.)p=rot(-PI/2.)*p;
                        if(p.y>k){
                                p = rot(-3./4.*PI)*(p-(h+c)*.5);
                        }else if(p.x+p.y<k){
                                p.x=-p.x;
                        }else{
                                type=1.;
                                if(p.x<0.){
                                        p = abs(rot(PI/8.+PI/2.)*(p-(e+g)*.5));
                                }else{
                                        p = abs(rot(PI/8.      )*(p-(e+b)*.5));
                                }
                        }

                }else{
                        if(dot(p-vw, uv-vw)<0.){
                                p = abs(rot(PI/2.)*p);
                                //O.x++;
                        }else if(dot(p-vw, u-vw)<0.){
                                p = abs(p-(v+vw)*.5);
                                //O.y++;
                        }else{
                                type = 0.;
                                p = rot(9./8.*PI)*(p-(u+uv)*.5);
                                //O.z++;
                        }

                }
                p /= k;
                s *= k;
        }

        float dist=1e8;
        if(type<.5) {    
                p = abs(rot(PI/4.)*(p-c));
                dist = min(p.x, p.y);
                O.y+=.2;
        }else{
                p = abs(rot(PI/8.)*(p-u));
                dist = p.y;
                O.z+=.4;
        }
        O +=.3;
        dist = dist * s;
        O += vec4( smoothstep( .1*6./R.y, 0., dist) );
}
